<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('projects/index.php');verify_csrf();$id=(int)($_POST['project_id']??0);$user=(int)current_user()['user_id'];$st=$pdo->prepare('SELECT saved_project_id FROM saved_projects WHERE user_id=? AND project_id=?');$st->execute([$user,$id]);if($st->fetchColumn()){$st=$pdo->prepare('DELETE FROM saved_projects WHERE user_id=? AND project_id=?');$st->execute([$user,$id]);flash('Project removed from saved items.','info');}else{$st=$pdo->prepare('INSERT IGNORE INTO saved_projects (user_id,project_id) VALUES (?,?)');$st->execute([$user,$id]);flash('Project saved.');}redirect('projects/view.php?id='.$id);
